import React, { useState, useEffect } from 'react';

const AlertsBanner = ({ alerts }) => {
  const [visibleAlerts, setVisibleAlerts] = useState(alerts || []);

  useEffect(() => {
    setVisibleAlerts(alerts || []);
  }, [alerts]);

  if (!visibleAlerts || visibleAlerts.length === 0) return null;

  const getAlertStyles = (type) => {
    switch (type) {
      case 'urgent':
        return 'bg-red-100 border-red-400 text-red-800';
      case 'warning':
        return 'bg-yellow-100 border-yellow-400 text-yellow-800';
      case 'info':
        return 'bg-blue-100 border-blue-400 text-blue-800';
      default:
        return 'bg-gray-100 border-gray-400 text-gray-800';
    }
  };

  const getAlertIcon = (type) => {
    switch (type) {
      case 'urgent':
        return '🚨';
      case 'warning':
        return '⚠️';
      case 'info':
        return 'ℹ️';
      default:
        return '📢';
    }
  };

  return (
    <div className="fixed top-0 left-0 right-0 z-30 space-y-2 p-4 max-h-96 overflow-y-auto">
      {visibleAlerts.map((alert, index) => (
        <div
          key={index}
          className={`border-l-4 p-4 rounded-lg shadow-lg flex items-start gap-3 animate-slide-down ${getAlertStyles(alert.type)}`}
        >
          <span className="text-2xl flex-shrink-0">{getAlertIcon(alert.type)}</span>
          <div className="flex-1">
            <h3 className="font-bold text-sm">{alert.title}</h3>
            <p className="text-xs mt-1">{alert.message}</p>
          </div>
          <button
            onClick={() => setVisibleAlerts(visibleAlerts.filter((_, i) => i !== index))}
            className="text-xl hover:opacity-70 flex-shrink-0"
          >
            ✕
          </button>
        </div>
      ))}
    </div>
  );
};

export default AlertsBanner;
